package com.hotel.hotelproject.repository; import com.hotel.hotelproject.model.*; import org.springframework.data.jpa.repository.*; import java.time.LocalDate; import java.util.*; public interface ReservationRepository extends JpaRepository<Reservation,Long> { boolean existsByRoomIdAndStatusInAndCheckInDateLessThanAndCheckOutDateGreaterThan(Long roomId,Collection<ReservationStatus> statuses,LocalDate checkOut,LocalDate checkIn); boolean existsByGuestId(Long id); List<Reservation> findByGuestId(Long id); boolean existsByRoomIdAndIdNotAndStatusInAndCheckInDateLessThanAndCheckOutDateGreaterThan(Long roomId,Long id,Collection<ReservationStatus> statuses,LocalDate checkOut,LocalDate checkIn);}
